function mergeSettings(defaults, user) {
  const result = { ...defaults, ...user };
  for (const key of Object.keys(user)) {
    const a = defaults[key], b = user[key];
    if (a && b && typeof a === "object" && typeof b === "object" && !Array.isArray(a) && !Array.isArray(b)) {
      result[key] = { ...a, ...b };
    }
  }
  return result;
}

function invert(obj) {
  return Object.fromEntries(Object.entries(obj).map(([k, v]) => [v, k]));
}

function summary({ name, age, city = "unknown", ...rest }) {
  let text = name;
  if (age !== undefined) text += ` (${age})`;
  text += ` from ${city}`;
  const extra = Object.keys(rest).length;
  if (extra > 0) text += `, ${extra} more ${extra === 1 ? "field" : "fields"}`;
  return text;
}

unitTests:
test("merge without changing inputs", () => {
  const defaults = { theme: "light", size: 12, colors: { bg: "white", fg: "black" } };
  const user = { size: 14, colors: { fg: "navy" } };
  const merged = mergeSettings(defaults, user);
  checkEq(merged, { theme: "light", size: 14, colors: { bg: "white", fg: "navy" } });
  checkEq(defaults.size, 12);
  checkEq(defaults.colors.fg, "black");
  checkEq(mergeSettings({ a: 1 }, {}), { a: 1 });
  checkEq(mergeSettings({ list: [1, 2] }, { list: [3] }), { list: [3] });
});

test("invert keys and values", () => {
  checkEq(invert({ a: "x", b: "y" }), { x: "a", y: "b" });
  checkEq(invert({}), {});
});

test("destructured summary", () => {
  checkEq(summary({ name: "Ada", age: 36, city: "London", job: "maths", pet: "cat" }), "Ada (36) from London, 2 more fields");
  checkEq(summary({ name: "Bob" }), "Bob from unknown");
  checkEq(summary({ name: "Cy", city: "Oslo", id: 4 }), "Cy from Oslo, 1 more field");
  checkEq(summary({ name: "Di", age: 0 }), "Di (0) from unknown");
});

